/* dust layer: scratch with a finger; reveals when ~55% is cleared */
function setupScratch(cv, onDone) {
  const g = cv.getContext("2d"); g.fillStyle = "#8a6a3a"; g.fillRect(0, 0, cv.width, cv.height);
  for (let k = 0; k < 900; k++) { g.fillStyle = `rgba(${120 + (k * 7) % 60},${90 + (k * 11) % 50},${40 + (k * 5) % 40},.9)`; g.fillRect((k * 131) % cv.width, (k * 71) % cv.height, 6 + k % 9, 3 + k % 6); }
  g.globalCompositeOperation = "destination-out"; let down = false, done = false, strokes = 0;
  const pos = e => { const r = cv.getBoundingClientRect(); return [(e.clientX - r.left) * cv.width / r.width, (e.clientY - r.top) * cv.height / r.height]; };
  const dot = e => { const [x, y] = pos(e); g.beginPath(); g.arc(x, y, 26, 0, 7); g.fill(); if (++strokes % 12 === 0) check(); };
  const check = () => { if (done) return; const d = g.getImageData(0, 0, cv.width, cv.height).data; let clear = 0; for (let i = 3; i < d.length; i += 16) if (d[i] === 0) clear++; if (clear / (d.length / 16) > .55) { done = true; cv.style.transition = "opacity .6s"; cv.style.opacity = "0"; setTimeout(onDone, 500); } };
  cv.addEventListener("pointerdown", e => { down = true; cv.setPointerCapture(e.pointerId); dot(e); }); cv.addEventListener("pointermove", e => { if (down) dot(e); }); ["pointerup", "pointercancel"].forEach(ev => cv.addEventListener(ev, () => { down = false; check(); }));
  cv.style.touchAction = "none";
}
